UPDATE ai_conversation_message SET content='',tool_calls='[]',tool_name=NULL,deleted=true,updated_at=CURRENT_TIMESTAMP,updated_by=NULL
WHERE tenant_id=CAST(current_setting('app.tenant_id') AS uuid)
AND conversation_id=#{id}

UPDATE ai_conversation_turn SET recovery_snapshot='[]',idempotency_key=CAST(id AS varchar),status='ERROR',error_code='conversation.deleted',deleted=true,updated_at=CURRENT_TIMESTAMP,updated_by=NULL
WHERE tenant_id=CAST(current_setting('app.tenant_id') AS uuid)
AND conversation_id=#{id}

UPDATE ai_conversation SET title='',instructions='',skill_snapshot='[]',mcp_snapshot='[]',active_turn_id=NULL,deleted=true,updated_at=CURRENT_TIMESTAMP,updated_by=NULL
WHERE tenant_id=CAST(current_setting('app.tenant_id') AS uuid)
AND id=#{id}
